<!doctype html><html><head><style>body{font-family:DejaVu Sans;font-size:10px;color:#302842}h1{color:#6d2b91}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.totals{margin-top:20px;width:45%;margin-left:auto}.totals td{border:0}</style></head><body><h1>{{$brandName}} — Collection report</h1><h2>{{$event->name}}</h2><p>{{$event->event_date->format('d M Y')}} · {{$event->venue}}</p><table><thead><tr><th>Name</th><th>Phone</th><th class="right">Due</th><th class="right">Paid</th><th>Status</th><th>Paid date</th></tr></thead><tbody>@foreach($event->contributions as $row)<tr><td>{{$row->contributor->name}}</td><td>{{$row->contributor->phone}}</td><td class="right">₹{{number_format($row->amount_due,2)}}</td><td class="right">₹{{number_format($row->amount_paid,2)}}</td><td>{{ucfirst(str_replace('_',' ',$row->payment_status))}}</td><td>{{$row->paid_at?->format('d M Y')}}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Total Expected</td><td class="right">₹{{number_format($totals['expected'],2)}}</td></tr><tr><td>Total Collected</td><td class="right">₹{{number_format($totals['collected'],2)}}</td></tr><tr><td><strong>Total Outstanding</strong></td><td class="right"><strong>₹{{number_format($totals['outstanding'],2)}}</strong></td></tr></table></body></html>
